 const countries=[...new Set(entries.map(e=>e.wine.country).filter(Boolean))],grapes=[...new Map(entries.flatMap(e=>grapeNames(e.wine.grape)).map(name=>[normalizeGrape(name),name])).values()].sort((a,b)=>a.localeCompare(b,'ru')),styles=[...new Set(entries.map(e=>e.wine.style).filter(Boolean))];
